mapper.select:
select

proc.C_Name as pConsName,
prod.D_Name as pCompDepName,
(select count(1) from OA_Attendance_Member oam where oam.Ag_Id=mn.Ag_Id) as memberCount,
mn.*
from OA_Attendance_Group mn

where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.P_Id = #{params.pId}


    and mn.Ag_State = #{params.agState}


    and mn.Ag_Scope = #{params.agScope}


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and mn.Ag_Name like concat('%',#{params.agName},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Ag_Create_Time desc
